// Minimalist Asteroid Escape game
// Targets <canvas id="game"></canvas>
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas with id "game" not found');
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.clientWidth || 800;
  const H = canvas.height = canvas.clientHeight || 600;

  // Ship definition
  const ship = {
    x: 100,
    y: H / 2,
    r: 15,
    angle: 0,
    vx: 0,
    vy: 0,
    thrust: 0.1,
    turnSpeed: 0.07,
  };

  // Input handling
  const keys = {};
  addEventListener('keydown', e => (keys[e.code] = true));
  addEventListener('keyup', e => (keys[e.code] = false));

  // Asteroid array
  const asteroids = [];
  const ASTEROID_INTERVAL = 1500; // ms
  let lastAsteroid = 0;

  // Game state
  let score = 0;
  let alive = true;

  function spawnAsteroid() {
    const size = 20 + Math.random() * 30;
    asteroids.push({
      x: W + size,
      y: Math.random() * H,
      r: size,
      speed: 1 + Math.random() * 2,
    });
  }

  function update(dt) {
    // Ship controls
    if (keys['ArrowLeft']) ship.angle -= ship.turnSpeed * dt;
    if (keys['ArrowRight']) ship.angle += ship.turnSpeed * dt;
    if (keys['ArrowUp']) {
      ship.vx += Math.cos(ship.angle) * ship.thrust * dt;
      ship.vy += Math.sin(ship.angle) * ship.thrust * dt;
    }
    // Apply friction
    ship.vx *= 0.99; ship.vy *= 0.99;
    ship.x += ship.vx * dt;
    ship.y += ship.vy * dt;
    // Keep ship in bounds
    if (ship.x < 0) ship.x = 0;
    if (ship.x > W) ship.x = W;
    if (ship.y < 0) ship.y = 0;
    if (ship.y > H) ship.y = H;

    // Asteroids
    const now = performance.now();
    if (now - lastAsteroid > ASTEROID_INTERVAL) {
      spawnAsteroid();
      lastAsteroid = now;
    }
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x -= a.speed * dt;
      if (a.x + a.r < 0) asteroids.splice(i, 1);
    }

    // Collision detection
    for (const a of asteroids) {
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.r + ship.r) {
        alive = false;
        break;
      }
    }

    if (alive) score += dt * 0.01;
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    // Ship
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.beginPath();
    ctx.moveTo(ship.r, 0);
    ctx.lineTo(-ship.r, ship.r / 2);
    ctx.lineTo(-ship.r, -ship.r / 2);
    ctx.closePath();
    ctx.fillStyle = '#0f0';
    ctx.fill();
    ctx.restore();
    // Asteroids
    ctx.fillStyle = '#888';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    }
    // Score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + Math.floor(score), 10, 20);
    if (!alive) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#f00';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', W / 2, H / 2);
    }
  }

  let last = performance.now();
  function loop() {
    const now = performance.now();
    const dt = (now - last) / 16; // normalize to ~60fps units
    last = now;
    if (alive) update(dt);
    draw();
    requestAnimationFrame(loop);
  }
  loop();
})();
